/**
 * Bootstrap a first workspace plus owner API key. Run once after migrations:
 *
 *   pnpm --filter @mailpelican/api bootstrap "My Workspace" "My Org" "1 Main St"
 *
 * The raw key is printed exactly once; only its hash is stored.
 */
import { loadEnv } from "@mailpelican/config";
import { apiKeys, closeDb, createDb, workspaces } from "@mailpelican/db";
import { eq } from "drizzle-orm";
import { issueApiKey } from "./routes/api-keys.js";

const [name, organizationName, postalAddress] = process.argv.slice(2);
if (name === undefined || organizationName === undefined || postalAddress === undefined) {
  console.error("usage: bootstrap <workspace-name> <organization-name> <postal-address>");
  process.exit(1);
}

const env = loadEnv();
const db = createDb(env.DATABASE_URL);

const slug = name
  .toLowerCase()
  .replaceAll(/[^a-z0-9]+/g, "-")
  .replaceAll(/(^-|-$)/g, "");

const inserted = await db
  .insert(workspaces)
  .values({ name, slug, organizationName, postalAddress })
  .onConflictDoNothing()
  .returning();
const workspace =
  inserted[0] ?? (await db.select().from(workspaces).where(eq(workspaces.slug, slug)).limit(1))[0];
if (workspace === undefined) {
  console.error("workspace insert failed");
  await closeDb(db);
  process.exit(1);
}
if (inserted[0] === undefined) {
  console.log(`workspace already exists: ${workspace.id} (${workspace.slug})`);
  await closeDb(db);
  process.exit(0);
}

const issued = issueApiKey();
await db.insert(apiKeys).values({
  workspaceId: workspace.id,
  name: "owner",
  prefix: issued.prefix,
  secretHash: issued.secretHash,
  scopes: ["read", "write", "send"],
});

console.log(`workspace: ${workspace.id} (${workspace.slug})`);
console.log(`owner api key (store it now): ${issued.raw}`);
await closeDb(db);

import { apiKeys, uuidv7 } from "@mailpelican/db";
import type { ApiKeyScope, Database } from "@mailpelican/db";
import { hashToken } from "@mailpelican/domain";
import { and, eq, isNull } from "drizzle-orm";
import type { Context, Next } from "hono";
import { HTTPException } from "hono/http-exception";
import type { Principal } from "./deps.js";

declare module "hono" {
  interface ContextVariableMap {
    principal: Principal;
    requestId: string;
  }
}

/** Assign a request id and echo it back on the response. */
export async function requestIdMiddleware(c: Context, next: Next) {
  const requestId = c.req.header("x-request-id") ?? uuidv7();
  c.set("requestId", requestId);
  await next();
  c.header("x-request-id", requestId);
}

function unauthorized(detail: string): never {
  throw new HTTPException(401, { message: detail });
}

/**
 * Bearer-token auth for scoped API keys. Keys have the form
 * `dk_<prefix>.<secret>`; only the SHA-256 of the secret is stored.
 */
export function createAuthMiddleware(db: Database) {
  return async function authMiddleware(c: Context, next: Next) {
    const header = c.req.header("authorization");
    if (header === undefined || !header.startsWith("Bearer ")) {
      unauthorized("Missing bearer token.");
    }
    const token = [REDACTED]"Bearer ".length);
    const match = /^dk_([A-Za-z0-9_-]{8})\.(.+)$/.exec(token);
    if (match === null) {
      unauthorized("Malformed API key.");
    }
    const [, prefix, secret] = match as unknown as [string, string, string];
    const rows = await db
      .select()
      .from(apiKeys)
      .where(and(eq(apiKeys.prefix, prefix), isNull(apiKeys.revokedAt)))
      .limit(1);
    const key = rows[0];
    if (key === undefined) {
      unauthorized("Unknown API key.");
    }
    if (key.expiresAt !== null && key.expiresAt.getTime() <= Date.now()) {
      unauthorized("API key expired.");
    }
    if (hashToken(secret) !== key.secretHash) {
      unauthorized("Invalid API key.");
    }
    c.set("principal", {
      workspaceId: key.workspaceId,
      actorType: "api_key",
      actorId: key.id,
      scopes: key.scopes,
    });
    await db.update(apiKeys).set({ lastUsedAt: new Date() }).where(eq(apiKeys.id, key.id));
    await next();
  };
}

/** Enforce that the principal carries the scope this route requires. */
export function requireScope(scope: ApiKeyScope) {
  return async (c: Context, next: Next) => {
    const principal = c.get("principal");
    if (!principal.scopes.includes(scope)) {
      throw new HTTPException(403, { message: `Missing required scope: ${scope}.` });
    }
    await next();
  };
}

{
  "name": "@mailpelican/testkit",
  "version": "0.0.0",
