import { defineConfig } from "vitest/config";

// PGlite-backed integration suites slow down under full-repo parallel load;
// the 5s default is the flake source, not the code.
export default defineConfig({
  test: { testTimeout: 15_000 },
});

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { auth, createTestContext, type TestContext } from "./test-utils.js";

let ctx: TestContext;

const SAMPLE = `<?xml version="1.0"?>
<feedback>
  <report_metadata>
    <org_name>google.com</org_name>
    <report_id>abc123</report_id>
    <date_range><begin>1752537600</begin><end>1752624000</end></date_range>
  </report_metadata>
  <policy_published>
    <domain>example.com</domain>
    <p>quarantine</p>
    <pct>100</pct>
  </policy_published>
  <record>
    <row>
      <source_ip>192.0.2.1</source_ip>
      <count>40</count>
      <policy_evaluated><disposition>none</disposition><dkim>pass</dkim><spf>pass</spf></policy_evaluated>
    </row>
    <identifiers><header_from>example.com</header_from></identifiers>
  </record>
  <record>
    <row>
      <source_ip>198.51.100.7</source_ip>
      <count>5</count>
      <policy_evaluated><disposition>quarantine</disposition><dkim>fail</dkim><spf>fail</spf></policy_evaluated>
    </row>
    <identifiers><header_from>example.com</header_from></identifiers>
  </record>
</feedback>`;

beforeAll(async () => {
  ctx = await createTestContext();
});

afterAll(async () => {
  await ctx.close();
});

function post(path: string, body: unknown) {
  return ctx.app.request(path, {
    method: "POST",
    headers: { ...auth(ctx), "content-type": "application/json" },
    body: JSON.stringify(body),
  });
}

describe("DMARC report ingestion", () => {
  it("stores a report idempotently and aggregates stats", async () => {
    const first = await post("/v1/deliverability/dmarc-reports", { xml: SAMPLE });
    expect(first.status).toBe(201);
    const stored = (await first.json()) as { stored: boolean; messages: number };
    expect(stored.stored).toBe(true);
    expect(stored.messages).toBe(45);

    const duplicate = await post("/v1/deliverability/dmarc-reports", { xml: SAMPLE });
    expect(duplicate.status).toBe(200);
    expect(((await duplicate.json()) as { stored: boolean }).stored).toBe(false);

    const stats = await ctx.app.request("/v1/deliverability/dmarc-reports?domain=example.com", {
      headers: auth(ctx),
    });
    expect(stats.status).toBe(200);
    const body = (await stats.json()) as {
      reports: number;
      messages: number;
      dispositions: Record<string, number>;
      spf: Record<string, number>;
      topSources: { ip: string; count: number }[];
    };
    expect(body.reports).toBe(1);
    expect(body.messages).toBe(45);
    expect(body.dispositions).toEqual({ none: 40, quarantine: 5 });
    expect(body.spf).toEqual({ pass: 40, fail: 5 });
    expect(body.topSources[0]).toEqual({ ip: "192.0.2.1", count: 40 });
  });

  it("rejects invalid XML with problem details", async () => {
    const res = await post("/v1/deliverability/dmarc-reports", { xml: "<p>hello</p>" });
    expect(res.status).toBe(400);
  });
});

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { auth, createTestContext, type TestContext } from "./test-utils.js";

let ctx: TestContext;

beforeAll(async () => {
  ctx = await createTestContext();
});

afterAll(async () => {
  await ctx.close();
});

function json(method: string, path: string, body?: unknown) {
  return ctx.app.request(path, {
    method,
    headers: { ...auth(ctx), "content-type": "application/json" },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });
}

describe("template versions", () => {
  it("keeps M1 behavior for plain subject/body versions", async () => {
    const template = (await (await json("POST", "/v1/templates", { name: "plain" })).json()) as {
      id: string;
    };
    const res = await json("POST", `/v1/templates/${template.id}/versions`, {
      subject: "Hello",
      bodyHtml: "<p>Hi {{ first_name }}</p>",
      bodyText: "Hi {{ first_name }}",
    });
    expect(res.status).toBe(201);
    const version = (await res.json()) as {
      editorSchemaVersion: string;
      bodyHtml: string;
      designJson: unknown;
    };
    expect(version.editorSchemaVersion).toBe("m1-simple");
    expect(version.bodyHtml).toBe("<p>Hi {{ first_name }}</p>");
    expect(version.designJson).toBeNull();
  });

  it("renders a design document into html/text artifacts at authoring time", async () => {
    const template = (await (await json("POST", "/v1/templates", { name: "designed" })).json()) as {
      id: string;
    };
    const res = await json("POST", `/v1/templates/${template.id}/versions`, {
      subject: "News",
      designJson: {
        type: "document",
        children: [
          { type: "heading", content: "Hi {{ first_name }}" },
          { type: "text", content: "Something happened." },
          { type: "button", label: "Read", href: "https://example.com/a" },
        ],
      },
    });
    expect(res.status).toBe(201);
    const version = (await res.json()) as {
      editorSchemaVersion: string;
      bodyHtml: string;
      bodyText: string;
    };
    expect(version.editorSchemaVersion).toBe("design-v1");
    expect(version.bodyHtml).toContain("<!DOCTYPE html");
    expect(version.bodyHtml).toContain("Hi {{ first_name }}");
    expect(version.bodyHtml).toContain('href="https://example.com/a"');
    expect(version.bodyText).toContain("Something happened.");
  });

  it("rejects an invalid design document with 400", async () => {
    const template = (await (await json("POST", "/v1/templates", { name: "broken" })).json()) as {
      id: string;
    };
    const res = await json("POST", `/v1/templates/${template.id}/versions`, {
      subject: "News",
      designJson: { type: "document", children: [{ type: "video", src: "x" }] },
    });
    expect(res.status).toBe(400);
  });
});

import { senderIdentities } from "@mailpelican/db";
import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { auth, createTestContext, type TestContext } from "./test-utils.js";

let ctx: TestContext;

beforeAll(async () => {
  ctx = await createTestContext();
});

afterAll(async () => {
  await ctx.close();
});

function json(method: string, path: string, body?: unknown) {
  return ctx.app.request(path, {
    method,
    headers: { ...auth(ctx), "content-type": "application/json" },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });
}

async function createIdentity(fromEmail: string) {
  const res = await json("POST", "/v1/sender-identities", {
    domain: "example.com",
    fromEmail,
    fromName: "News",
  });
  expect(res.status).toBe(201);
  return ((await res.json()) as { id: string }).id;
}

describe("sender identity DNS verification", () => {
  it("verifies when the expected records resolve", async () => {
    const id = await createIdentity("news@example.com");
    const res = await json("POST", `/v1/sender-identities/${id}/verify`);
    expect(res.status).toBe(200);
    const body = (await res.json()) as { verificationStatus: string; dns: { found: boolean }[] };
    expect(body.verificationStatus).toBe("verified");
    expect(body.dns.every((r) => r.found)).toBe(true);
  });

  it("fails closed with 422 and per-record detail when DNS is missing", async () => {
    const id = await createIdentity("missing@example.com");
    const original = ctx.deps.resolveDns;
    ctx.deps.resolveDns = async () => [];
    try {
      const res = await json("POST", `/v1/sender-identities/${id}/verify`);
      expect(res.status).toBe(422);
      const body = (await res.json()) as { detail: string };
      expect(body.detail).toContain("TXT example.com");
      expect(body.detail).toContain("_dmarc.example.com");
    } finally {
      ctx.deps.resolveDns = original;
    }
    const rows = await ctx.db
      .select({ status: senderIdentities.verificationStatus })
      .from(senderIdentities)
      .where(eq(senderIdentities.id, id));
    expect(rows[0]?.status).toBe("failed");
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createApi, loadApiKey, storeApiKey, clearApiKey, ApiError } from "./api.js";

const storage = new Map<string, string>();

beforeEach(() => {
  storage.clear();
  vi.stubGlobal("localStorage", {
    getItem: (key: string) => storage.get(key) ?? null,
    setItem: (key: string, value: string) => void storage.set(key, value),
    removeItem: (key: string) => void storage.delete(key),
  });
});

afterEach(() => {
  vi.unstubAllGlobals();
});

function stubFetch(status: number, body: unknown) {
  const calls: { url: string; init: RequestInit | undefined }[] = [];
  vi.stubGlobal("fetch", (url: string, init?: RequestInit) => {
    calls.push({ url, init });
    return Promise.resolve(
      new Response(JSON.stringify(body), {
        status,
        headers: { "content-type": "application/json" },
      }),
    );
  });
  return calls;
}

describe("api client", () => {
  it("round-trips the stored key", () => {
    expect(loadApiKey()).toBeNull();
    storeApiKey("dk_test");
    expect(loadApiKey()).toBe("dk_test");
    clearApiKey();
    expect(loadApiKey()).toBeNull();
  });

  it("sends the bearer key and builds cursor URLs", async () => {
    const calls = stubFetch(200, { data: [], pageInfo: { nextCursor: null, hasNextPage: false } });
    storeApiKey("dk_abc");
    const api = createApi(loadApiKey, () => {});
    await api.listCampaigns("cursor-1");
    expect(calls[0]?.url).toBe("/v1/campaigns?limit=50&cursor=cursor-1");
    const headers = new Headers(calls[0]?.init?.headers);
    expect(headers.get("authorization")).toBe("Bearer dk_abc");
  });

  it("maps problem details to ApiError", async () => {
    stubFetch(404, { status: 404, detail: "Campaign not found." });
    const api = createApi(loadApiKey, () => {});
    const failure = await api.campaignStats("x").catch((err: unknown) => err);
    expect(failure).toBeInstanceOf(ApiError);
    expect((failure as ApiError).status).toBe(404);
    expect((failure as ApiError).message).toBe("Campaign not found.");
  });

  it("clears the key and notifies on 401", async () => {
    stubFetch(401, { status: 401, detail: "unauthorized" });
    storeApiKey("dk_stale");
    let notified = false;
    const api = createApi(loadApiKey, () => {
      notified = true;
    });
    await api.listLists(null).catch(() => {});
    expect(loadApiKey()).toBeNull();
    expect(notified).toBe(true);
  });
});

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { auth, createTestContext, type TestContext } from "./test-utils.js";

let ctx: TestContext;

beforeAll(async () => {
  ctx = await createTestContext();
});

afterAll(async () => {
  await ctx.close();
});

describe("app shell", () => {
  it("answers liveness without touching dependencies", async () => {
    const res = await ctx.app.request("/health/live");
    expect(res.status).toBe(200);
  });

  it("returns request ids on responses", async () => {
    const res = await ctx.app.request("/health/live");
    expect(res.headers.get("x-request-id")).toBeTruthy();
  });

  it("answers unknown routes with a problem-details 404", async () => {
    const res = await ctx.app.request("/nope");
    expect(res.status).toBe(404);
    expect(res.headers.get("content-type")).toContain("application/problem+json");
    expect(await res.json()).toMatchObject({ status: 404, title: "Not Found" });
  });

  it("exposes the OpenAPI document", async () => {
    const res = await ctx.app.request("/v1/openapi.json");
    expect(res.status).toBe(200);
    const doc = (await res.json()) as { paths: Record<string, unknown> };
    expect(doc.paths["/contacts"]).toBeDefined();
    expect(doc.paths["/campaigns/{id}/confirm-send"]).toBeDefined();
  });
});

describe("auth", () => {
  it("rejects requests without a bearer token", async () => {
    const res = await ctx.app.request("/v1/contacts");
    expect(res.status).toBe(401);
    expect(await res.json()).toMatchObject({ status: 401 });
  });

  it("rejects malformed keys", async () => {
    const res = await ctx.app.request("/v1/contacts", {
      headers: { authorization: "Bearer nope" },
    });
    expect(res.status).toBe(401);
  });

  it("rejects wrong secrets", async () => {
    const [prefix] = ctx.rawKey.split(".");
    const res = await ctx.app.request("/v1/contacts", {
      headers: { authorization: `Bearer ${prefix}.wrongsecretwrongsecret` },
    });
    expect(res.status).toBe(401);
  });

  it("enforces scopes", async () => {
    const readOnly = await createTestContext({ scopes: ["read"] });
    try {
      const res = await readOnly.app.request("/v1/contacts", {
        method: "POST",
        headers: { ...auth(readOnly), "content-type": "application/json" },
        body: JSON.stringify({ email: "a@b.co" }),
      });
      expect(res.status).toBe(403);
      expect(await res.json()).toMatchObject({ status: 403, title: "Forbidden" });
    } finally {
      await readOnly.close();
    }
  });

  it("rejects validation errors with problem details", async () => {
    const res = await ctx.app.request("/v1/contacts", {
      method: "POST",
      headers: { ...auth(ctx), "content-type": "application/json" },
      body: JSON.stringify({ email: "not-an-email" }),
    });
    expect(res.status).toBe(400);
    const body = (await res.json()) as { status: number; title: string; detail?: string };
    expect(body).toMatchObject({ status: 400, title: "Bad Request" });
    expect(body.detail).toContain("email");
  });
});

import {
  campaignRecipients,
  campaigns,
  campaignVersions,
  contacts,
  events,
  messages,
  relays,
  uuidv7,
} from "@mailpelican/db";
import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { auth, createTestContext, type TestContext } from "./test-utils.js";

let ctx: TestContext;
let campaignId: string;
let messageId: string;

beforeAll(async () => {
  ctx = await createTestContext();
  const relayId = uuidv7();
  await ctx.db.insert(relays).values({
    id: relayId,
    workspaceId: ctx.workspaceId,
    type: "ses",
    name: "r",
    credentialsEncrypted: "v1.x.y.z",
    capabilities: {
      providerIdempotency: true,
      deliveryEvents: true,
      bounceEvents: true,
      complaintEvents: true,
      scheduling: false,
    },
  });
  const contactId = uuidv7();
  await ctx.db.insert(contacts).values({
    id: contactId,
    workspaceId: ctx.workspaceId,
    emailNormalized: "ada@example.com",
    emailOriginal: "ada@example.com",
  });
  campaignId = uuidv7();
  await ctx.db.insert(campaigns).values({
    id: campaignId,
    workspaceId: ctx.workspaceId,
    name: "June",
    status: "completed",
  });
  const versionId = uuidv7();
  await ctx.db.insert(campaignVersions).values({
    id: versionId,
    campaignId,
    version: 1,
    subject: "s",
    fromName: "News",
    fromEmail: "news@example.com",
    bodyHtml: "<p>Hi</p>",
    bodyText: "Hi",
    audienceRef: uuidv7(),
  });
  const recipientId = uuidv7();
  await ctx.db.insert(campaignRecipients).values({
    id: recipientId,
    campaignId,
    campaignVersionId: versionId,
    contactId,
    email: "ada@example.com",
    status: "included",
  });
  messageId = recipientId;
  await ctx.db.insert(messages).values({
    id: messageId,
    workspaceId: ctx.workspaceId,
    campaignId,
    campaignRecipientId: recipientId,
    contactId,
    relayId,
    status: "delivered",
  });
});

afterAll(async () => {
  await ctx.close();
});

async function recordedEvents() {
  return ctx.db.select().from(events).where(eq(events.messageId, messageId));
}

describe("open/click tracking", () => {
  it("serves the pixel and records an open per request", async () => {
    const res = await ctx.app.request(`/v1/track/open/${messageId}`);
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toBe("image/gif");
    expect(res.headers.get("cache-control")).toContain("no-store");
    const body = new Uint8Array(await res.arrayBuffer());
    expect(body.length).toBeGreaterThan(30);

    await ctx.app.request(`/v1/track/open/${messageId}`);
    const rows = await recordedEvents();
    expect(rows.filter((r) => r.type === "opened")).toHaveLength(2);
  });

  it("redirects clicks and records the destination", async () => {
    const res = await ctx.app.request(
      `/v1/track/click/${messageId}?url=${encodeURIComponent("https://example.com/a?x=1")}`,
    );
    expect(res.status).toBe(302);
    expect(res.headers.get("location")).toBe("https://example.com/a?x=1");
    const rows = await recordedEvents();
    const click = rows.find((r) => r.type === "clicked");
    expect(click?.meta.url).toBe("https://example.com/a?x=1");
  });

  it("rejects non-http destinations", async () => {
    for (const bad of ["javascript:alert(1)", "ftp://example.com/x", "not-a-url"]) {
      const res = await ctx.app.request(
        `/v1/track/click/${messageId}?url=${encodeURIComponent(bad)}`,
      );
      expect(res.status).toBe(400);
    }
  });

  it("serves unknown message ids without recording", async () => {
    const unknown = uuidv7();
    const open = await ctx.app.request(`/v1/track/open/${unknown}`);
    expect(open.status).toBe(200);
    const click = await ctx.app.request(
      `/v1/track/click/${unknown}?url=${encodeURIComponent("https://example.com/")}`,
    );
    expect(click.status).toBe(302);
    const rows = await ctx.db.select().from(events).where(eq(events.messageId, unknown));
    expect(rows).toHaveLength(0);
  });

  it("surfaces opens and clicks in campaign stats", async () => {
