    try {
      const campaigns = (await (
        await ctx.app.request("/v1/campaigns", { headers: auth(ctx) })
      ).json()) as { data: { id: string }[] };
      const res = await ctx.app.request(`/v1/campaigns/${campaigns.data[0]?.id}/preview`, {
        method: "POST",
