async function prepareFor(
  target: TestContext,
  headers: Record<string, string>,
  campaignId: string,
) {
  const prep = await target.app.request(`/v1/campaigns/${campaignId}/prepare`, {
    method: "POST",
    headers,
  });
  expect(prep.status).toBe(200);
  return (await prep.json()) as { confirmationToken: string; approvalRequired: boolean };
}

describe("approval threshold", () => {
  it("requires an explicit approved flag above the threshold", async () => {
    const gated = await createTestContext({
      scopes: ["read", "write", "send"],
      approvalThreshold: 1,
    });
    try {
      const { headers, campaignId } = await campaignWithAudience(gated, ["a@x.co", "b@x.co"]);
      const first = await prepareFor(gated, headers, campaignId);
      expect(first.approvalRequired).toBe(true);

      const denied = await gated.app.request(`/v1/campaigns/${campaignId}/confirm-send`, {
        method: "POST",
        headers: { ...headers, "idempotency-key": "c1" },
        body: JSON.stringify({ confirmationToken: [REDACTED] }),
      });
      expect(denied.status).toBe(403);
      expect(((await denied.json()) as { detail: string }).detail).toContain("approval threshold");

      // A rejection burns the token, so approve with a fresh prepare.
      const second = await prepareFor(gated, headers, campaignId);
      const approved = await gated.app.request(`/v1/campaigns/${campaignId}/confirm-send`, {
        method: "POST",
        headers: { ...headers, "idempotency-key": "c2" },
        body: JSON.stringify({ confirmationToken: [REDACTED], approved: true }),
      });
      expect(approved.status).toBe(200);
    } finally {
      await gated.close();
    }
  });

  it("sends without approval at or under the threshold", async () => {
    const gated = await createTestContext({
      scopes: ["read", "write", "send"],
      approvalThreshold: 5,
    });
    try {
      const { headers, campaignId } = await campaignWithAudience(gated, ["a@x.co", "b@x.co"]);
      const prepared = await prepareFor(gated, headers, campaignId);
      expect(prepared.approvalRequired).toBe(false);
      const confirm = await gated.app.request(`/v1/campaigns/${campaignId}/confirm-send`, {
        method: "POST",
        headers: { ...headers, "idempotency-key": "c1" },
        body: JSON.stringify({ confirmationToken: [REDACTED] }),
      });
      expect(confirm.status).toBe(200);
    } finally {
      await gated.close();
    }
  });
});

import { drainOutboxOnce, createMemoryRateLimiter } from "@mailpelican/queue";
import {
  consentEvents,
  confirmationTokens,
  contacts,
  outbox,
  suppressions,
  uuidv7,
} from "@mailpelican/db";
import { and, eq } from "drizzle-orm";
import { generateToken } from "@mailpelican/domain";
import { sendSubscriptionConfirmation, type PipelineDeps } from "@mailpelican/worker";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { auth, createTestContext, testEnv, type TestContext } from "./test-utils.js";

/**
 * Double opt-in end to end: public subscribe → pending membership → outbox →
 * worker confirmation email → single-use confirm → subscribed with a
 * `confirmed` consent event.
 */

let ctx: TestContext;
let pipeline: PipelineDeps;
let listId: string;

beforeAll(async () => {
  ctx = await createTestContext();
  pipeline = {
    db: ctx.db,
    env: testEnv(),
    limiter: createMemoryRateLimiter(),
    createProvider: async () => ctx.fakeRelay,
  };

  const listRes = await json("POST", "/v1/lists", { name: "newsletter" });
  expect(listRes.status).toBe(201);
  listId = ((await listRes.json()) as { id: string }).id;

  const relayRes = await json("POST", "/v1/relays", {
    type: "ses",
    name: "default",
    credentials: { region: "us-east-1", accessKeyId: "x", secretAccessKey: "y" },
    capabilities: ctx.fakeRelay.capabilities,
    isDefault: true,
  });
  expect(relayRes.status).toBe(201);
  const relay = (await relayRes.json()) as { id: string };
  await json("POST", `/v1/relays/${relay.id}/test-connection`);

  const identityRes = await json("POST", "/v1/sender-identities", {
    relayId: relay.id,
    domain: "example.com",
    fromEmail: "news@example.com",
    fromName: "News",
  });
  expect(identityRes.status).toBe(201);
  const identity = (await identityRes.json()) as { id: string };
  await json("POST", `/v1/sender-identities/${identity.id}/verify`);
});

afterAll(async () => {
  await ctx.close();
});

function json(
  method: string,
  path: string,
  body?: unknown,
  extraHeaders: Record<string, string> = {},
) {
  return ctx.app.request(path, {
    method,
    headers: { ...auth(ctx), "content-type": "application/json", ...extraHeaders },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });
}

/** Public routes take no API key. */
function postPublic(path: string, body?: unknown) {
  return ctx.app.request(path, {
    method: "POST",
    headers: { "content-type": "application/json" },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });
}

async function confirmOutboxRows() {
  return ctx.db
    .select()
    .from(outbox)
    .where(and(eq(outbox.workspaceId, ctx.workspaceId), eq(outbox.topic, "subscription.confirm")));
}

async function runOutbox() {
  await drainOutboxOnce({
    db: ctx.db,
    enqueue: async (topic, payload) => {
      if (topic === "subscription.confirm") {
        await sendSubscriptionConfirmation(
          pipeline,
          payload as { workspaceId: string; contactId: string; listId: string },
        );
      }
    },
  });
}

describe("double opt-in", () => {
  it("runs the full loop: subscribe, confirm email, single-use confirm", async () => {
    const res = await postPublic("/v1/public/subscribe", {
      listId,
      email: "Ada@Example.com",
      customFields: { first_name: "Ada" },
    });
    expect(res.status).toBe(200);
    expect(((await res.json()) as { state: string }).state).toBe("pending");

    const membership = await ctx.db.query.listMemberships.findFirst({
      where: (t, { eq: e }) => e(t.listId, listId),
    });
    expect(membership?.state).toBe("pending");
    expect(await confirmOutboxRows()).toHaveLength(1);

    await runOutbox();
    expect(ctx.fakeRelay.sent).toHaveLength(1);
    const sentMessage = ctx.fakeRelay.sent[0]?.message;
    expect(sentMessage?.toEmail).toBe("ada@example.com");
    const match = /\/v1\/public\/confirm\/([A-Za-z0-9_-]+)/.exec(sentMessage?.html ?? "");
    expect(match).not.toBeNull();
    const rawToken = match?.[1] ?? "";

    const describeRes = await ctx.app.request(`/v1/public/confirm/${rawToken}`);
    expect(describeRes.status).toBe(200);
    expect(((await describeRes.json()) as { email: string }).email).toBe("ad***@example.com");

    const confirmRes = await postPublic(`/v1/public/confirm/${rawToken}`);
    expect(confirmRes.status).toBe(200);
    expect(((await confirmRes.json()) as { state: string }).state).toBe("subscribed");

    const confirmed = await ctx.db.query.listMemberships.findFirst({
      where: (t, { eq: e }) => e(t.listId, listId),
    });
    expect(confirmed?.state).toBe("subscribed");

    const events = await ctx.db
      .select({ type: consentEvents.type, source: consentEvents.source })
      .from(consentEvents)
      .where(eq(consentEvents.workspaceId, ctx.workspaceId));
    expect(events.map((e) => e.type)).toEqual(["requested", "confirmed"]);

    // Single-use: a replay is 410 and does not insert a second consent event.
    const replay = await postPublic(`/v1/public/confirm/${rawToken}`);
    expect(replay.status).toBe(410);
    const eventsAfter = await ctx.db
      .select({ type: consentEvents.type })
      .from(consentEvents)
      .where(eq(consentEvents.workspaceId, ctx.workspaceId));
    expect(eventsAfter).toHaveLength(2);
  });

  it("re-requesting while subscribed is a no-op without a new email", async () => {
    const res = await postPublic("/v1/public/subscribe", { listId, email: "ada@example.com" });
    expect(res.status).toBe(200);
    expect(((await res.json()) as { state: string }).state).toBe("subscribed");
    expect(await confirmOutboxRows()).toHaveLength(1);
    expect(ctx.fakeRelay.sendCalls).toBe(1);
  });

  it("answers suppressed addresses identically without writes or email", async () => {
    await ctx.db.insert(suppressions).values({
      workspaceId: ctx.workspaceId,
      emailNormalized: "bounce@example.com",
      reason: "hard_bounce",
      source: "webhook",
    });
    const res = await postPublic("/v1/public/subscribe", { listId, email: "bounce@example.com" });
    expect(res.status).toBe(200);
    expect(((await res.json()) as { state: string }).state).toBe("pending");
    expect(await confirmOutboxRows()).toHaveLength(1);
    const contact = await ctx.db.query.contacts.findFirst({
      where: (t, { eq: e }) => e(t.emailNormalized, "bounce@example.com"),
    });
    expect(contact).toBeUndefined();
  });

  it("rejects unknown lists and invalid tokens", async () => {
    const unknownList = await postPublic("/v1/public/subscribe", {
      listId: uuidv7(),
      email: "x@example.com",
    });
    expect(unknownList.status).toBe(404);

    const unknownToken = await postPublic("/v1/public/confirm/not-a-token");
    expect(unknownToken.status).toBe(404);

    const expired = generateToken();
    const contactId = uuidv7();
    await ctx.db.insert(contacts).values({
      id: contactId,
      workspaceId: ctx.workspaceId,
      emailNormalized: "expired@example.com",
      emailOriginal: "expired@example.com",
    });
    await ctx.db.insert(confirmationTokens).values({
      workspaceId: ctx.workspaceId,
      contactId,
      listId,
      action: "confirm_subscription",
      tokenHash: expired.hash,
      expiresAt: new Date(Date.now() - 1000),
    });
    const expiredRes = await postPublic(`/v1/public/confirm/${expired.raw}`);
    expect(expiredRes.status).toBe(404);
  });
});

import { createRoute, z } from "@hono/zod-openapi";
import {
  auditEvents,
  campaignRecipients,
  events,
  inboundWebhookEvents,
  messages,
  replayInboundWebhook,
  appendOutbox,
  OUTBOX_TOPICS,
} from "@mailpelican/db";
import { DomainError } from "@mailpelican/domain";
import { and, asc, eq, gt, inArray, sql } from "drizzle-orm";
import { HTTPException } from "hono/http-exception";
import type { Deps, Principal } from "../deps.js";
import { parsePagination, toCursorPage } from "../http.js";
import {
  createRouter,
  dataPageSchema,
  dataSchema,
  idParamSchema,
  jsonOk,
  paginationQuerySchema,
  problemResponses,
} from "./helpers.js";

/** Normalized provider events, campaign stats, audit trail, webhook admin. */
export function observabilityRoutes(deps: Deps) {
  const app = createRouter();

  app.openapi(
    createRoute({
      method: "get",
      path: "/events",
      tags: ["events"],
      request: {
        query: paginationQuerySchema.extend({
          messageId: z.string().uuid().optional(),
          campaignId: z.string().uuid().optional(),
        }),
      },
      responses: { ...jsonOk(dataPageSchema, "Page of events."), ...problemResponses(400) },
    }),
    async (c) => {
      const { workspaceId } = c.get("principal") as Principal;
      const { after, limit } = parsePagination(c);
      const query = c.req.valid("query");
      const rows = await deps.db
        .select({
          event: events,
          campaignId: messages.campaignId,
        })
        .from(events)
        .leftJoin(messages, eq(events.messageId, messages.id))
        .where(
          and(
            eq(events.workspaceId, workspaceId),
            ...(query.messageId !== undefined ? [eq(events.messageId, query.messageId)] : []),
            ...(query.campaignId !== undefined ? [eq(messages.campaignId, query.campaignId)] : []),
            ...(after !== null ? [gt(events.id, after)] : []),
          ),
        )
        .orderBy(asc(events.id))
        .limit(limit + 1);
      const page = toCursorPage(
        rows.map((r) => ({ ...r.event, campaignId: r.campaignId })),
        limit,
      );
      return c.json(page, 200);
    },
  );

  app.openapi(
    createRoute({
      method: "get",
      path: "/stats/campaigns/{id}",
      tags: ["stats"],
      request: { params: idParamSchema },
      responses: { ...jsonOk(dataSchema, "Campaign totals."), ...problemResponses(404) },
    }),
    async (c) => {
      const { workspaceId } = c.get("principal") as Principal;
      const campaignId = c.req.valid("param").id;
      const messageCounts = await deps.db
        .select({ status: messages.status, count: sql<number>`count(*)::int` })
        .from(messages)
        .where(and(eq(messages.workspaceId, workspaceId), eq(messages.campaignId, campaignId)))
        .groupBy(messages.status);
      if (messageCounts.length === 0) {
        const recipientProbe = await deps.db
          .select({ count: sql<number>`count(*)::int` })
          .from(campaignRecipients)
          .where(eq(campaignRecipients.campaignId, campaignId));
        if ((recipientProbe[0]?.count ?? 0) === 0) {
          throw new HTTPException(404, { message: "Campaign not found." });
        }
      }
      const recipientCounts = await deps.db
        .select({ status: campaignRecipients.status, count: sql<number>`count(*)::int` })
        .from(campaignRecipients)
        .where(eq(campaignRecipients.campaignId, campaignId))
        .groupBy(campaignRecipients.status);
      const eventCounts = await deps.db
        .select({ type: events.type, count: sql<number>`count(*)::int` })
        .from(events)
        .innerJoin(messages, eq(events.messageId, messages.id))
        .where(and(eq(events.workspaceId, workspaceId), eq(messages.campaignId, campaignId)))
        .groupBy(events.type);
      const engagement = await deps.db
        .select({
          type: events.type,
          uniques: sql<number>`count(distinct ${events.messageId})::int`,
        })
        .from(events)
        .innerJoin(messages, eq(events.messageId, messages.id))
        .where(
          and(
            eq(events.workspaceId, workspaceId),
            eq(messages.campaignId, campaignId),
            inArray(events.type, ["opened", "clicked"]),
          ),
        )
        .groupBy(events.type);
      const uniqueByType = Object.fromEntries(engagement.map((r) => [r.type, r.uniques]));
      const byStatus = Object.fromEntries(messageCounts.map((r) => [r.status, r.count]));
      const byType = Object.fromEntries(eventCounts.map((r) => [r.type, r.count]));
      return c.json(
        {
          campaignId,
          messages: byStatus,
          recipients: Object.fromEntries(recipientCounts.map((r) => [r.status, r.count])),
          events: byType,
          totals: {
            sent:
              (byStatus.accepted ?? 0) +
              (byStatus.delivered ?? 0) +
              (byStatus.bounced ?? 0) +
              (byStatus.complained ?? 0),
            delivered: byStatus.delivered ?? 0,
            bounced: byStatus.bounced ?? 0,
            complained: byStatus.complained ?? 0,
            failed: byStatus.failed ?? 0,
            uniqueOpens: uniqueByType.opened ?? 0,
            uniqueClicks: uniqueByType.clicked ?? 0,
          },
        },
        200,
      );
    },
  );

  app.openapi(
    createRoute({
      method: "get",
      path: "/audit-events",
      tags: ["audit"],
      request: { query: paginationQuerySchema },
      responses: { ...jsonOk(dataPageSchema, "Page of audit events."), ...problemResponses(400) },
    }),
    async (c) => {
      const { workspaceId } = c.get("principal") as Principal;
      const { after, limit } = parsePagination(c);
      const rows = await deps.db
        .select()
        .from(auditEvents)
        .where(
          and(
            eq(auditEvents.workspaceId, workspaceId),
            ...(after !== null ? [gt(auditEvents.id, after)] : []),
          ),
        )
        .orderBy(asc(auditEvents.id))
        .limit(limit + 1);
      return c.json(toCursorPage(rows, limit), 200);
    },
  );

  app.openapi(
    createRoute({
      method: "post",
      path: "/webhook-deliveries/{id}/replay",
      tags: ["webhooks"],
      request: { params: idParamSchema },
      responses: { ...jsonOk(dataSchema, "Replay scheduled."), ...problemResponses(404) },
    }),
    async (c) => {
      const { workspaceId } = c.get("principal") as Principal;
      const replay = await replayInboundWebhook(deps.db, c.req.valid("param").id);
      if (replay === null || replay.workspaceId !== workspaceId) {
        throw new DomainError("not_found", "Webhook delivery not found.", 404);
      }
      await appendOutbox(deps.db, {
        workspaceId,
        topic: OUTBOX_TOPICS.webhookNormalize,
        payload: { workspaceId, inboxId: replay.id, relayId: replay.relayId },
      });
      return c.json({ id: replay.id, replayOf: replay.replayOf }, 200);
    },
  );

  app.openapi(
    createRoute({
      method: "get",
      path: "/webhook-deliveries",
      tags: ["webhooks"],
      request: {
        query: paginationQuerySchema.extend({
          status: z.enum(["received", "processed", "failed", "dead"]).optional(),
        }),
      },
      responses: {
        ...jsonOk(dataPageSchema, "Page of webhook deliveries."),
        ...problemResponses(400),
      },
    }),
    async (c) => {
      const { workspaceId } = c.get("principal") as Principal;
      const { after, limit } = parsePagination(c);
      const status = c.req.valid("query").status;
      const rows = await deps.db
        .select()
        .from(inboundWebhookEvents)
        .where(
          and(
            eq(inboundWebhookEvents.workspaceId, workspaceId),
            ...(status !== undefined ? [eq(inboundWebhookEvents.status, status)] : []),
            ...(after !== null ? [gt(inboundWebhookEvents.id, after)] : []),
          ),
        )
        .orderBy(asc(inboundWebhookEvents.id))
        .limit(limit + 1);
      return c.json(toCursorPage(rows, limit), 200);
    },
  );

  return app;
}

import { describe, expect, it } from "vitest";
import { initialBucket, retryAfterMs, takeToken } from "./rate-limit.js";

const config = { ratePerSecond: 2, burst: 3 };

describe("token bucket", () => {
  it("allows up to the burst then blocks", () => {
    let state = initialBucket(config);
    for (let i = 0; i < 3; i += 1) {
      const result = takeToken(state, config, 1000);
      expect(result.allowed).toBe(true);
      state = result.state;
    }
    expect(takeToken(state, config, 1000).allowed).toBe(false);
  });

  it("refills at the configured rate", () => {
    let state = initialBucket(config);
    state = takeToken(state, config, 0).state;
    state = takeToken(state, config, 0).state;
    state = takeToken(state, config, 0).state;
    const denied = takeToken(state, config, 0);
    expect(denied.allowed).toBe(false);
    const afterHalfSecond = takeToken(denied.state, config, 500);
    expect(afterHalfSecond.allowed).toBe(true);
  });

  it("never exceeds the burst ceiling", () => {
    const state = takeToken(initialBucket(config), config, 60_000).state;
    expect(state.tokens).toBeLessThanOrEqual(config.burst);
  });

  it("reports time until the next token", () => {
    const empty = { tokens: 0, updatedAtMs: 0 };
    expect(retryAfterMs(empty, config)).toBe(500);
    expect(retryAfterMs({ tokens: 2, updatedAtMs: 0 }, config)).toBe(0);
  });
});
